/* Offline UI reference only. All records and mutations are illustrative. */
'use strict';
const screens = { landing:'01 · Homepage', homeowners:'02 · For homeowners', explore:'03 · Find a home', listing:'04 · Home detail', login:'05 · Account / email link', booking:'06 · Booking · three steps', confirmation:'07 · Booking confirmed', trips:'08 · Your stays', trip:'09 · Stay details / cancellation', messages:'10 · Messages', passport:'11 · Profile / Trust Passport', host:'12 · Your homes', edit:'13 · Guided listing / edit', payouts:'14 · Payouts', claims:'15 · Claims', claim:'16 · Claim detail', review:'17 · Write a review', ops:'18 · Operations' };
const state = { page:'landing', view:'default', signedIn:false, intent:'renter', next:'explore', bookingStep:1, editStep:1, sent:false, checkIn:'2026-10-01', checkOut:'2026-10-31', guests:2, city:'Hudson', query:'', draftSaved:false, canceled:false, published:false, payoutReady:false, message:'', reviewSent:false, claimDisputed:false, bookingConfirmed:false };
const $ = (sel) => document.querySelector(sel);
const esc = (v) => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(cents/100);
const img = (cls='') => `<img class="${cls}" src="assets/home-concept.png" alt="Illustrative sunlit living room with an oak table, cream sofa and leafy outlook" width="1536" height="1024">`;
const link = (page,label,kind='') => `<a class="btn ${kind}" href="#${page}">${label}</a>`;
const button = (action,label,kind='') => `<button type="button" class="btn ${kind}" data-action="${action}">${label}</button>`;
const brand = `<a href="#landing" class="brand" aria-label="Stead home"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3.5 10.6 L12 3.4 L20.5 10.6 V20.5 H3.5 Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><circle cx="12" cy="12.6" r="2.1" fill="currentColor"/><path d="M12 14.6 V17.2" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>stead</a>`;
function header(){const member=state.signedIn||['confirmation','trips','trip','messages','passport','host','edit','payouts','claims','claim','review','ops'].includes(state.page);return `<header class="site-header">${brand}<nav aria-label="Primary"><a href="#explore" class="${state.page==='explore'?'active':''}">Find a home</a><a href="#homeowners" class="${state.page==='homeowners'?'active':''}">For homeowners</a>${member?'<a href="#trips">Your stays</a><a href="#messages">Messages</a>':''}</nav><div class="right">${member?'<a href="#passport">Your profile</a>':'<a href="#login" data-next="explore">Sign in</a>'}${link(member?'host':'homeowners',member?'Your homes':'List your home','secondary')}</div></header>`}
function footer(){return `<footer class="footer"><span>Stead · Homes for 30 nights or more.</span><div class="link-list"><a href="#explore">Find a home</a><a href="#homeowners">For homeowners</a></div></footer>`}
function bottom(){return `<nav class="mobile-bottom" aria-label="Member navigation">${[['explore','Explore'],['trips','Stays'],['messages','Messages'],['passport','Profile'],['host','Homes']].map(([id,label])=>`<a href="#${id}" class="${state.page===id?'active':''}">${label}</a>`).join('')}</nav>`}
function hostNav(){return `<nav class="nav-tabs" aria-label="Homeowner tools">${[['host','Your homes'],['payouts','Payouts'],['claims','Claims']].map(([id,label])=>`<a href="#${id}" class="${state.page===id?'active':''}">${label}</a>`).join('')}</nav>`}
function homeCard(){return `<a class="home-card" href="#listing">${img()}<h3>The house by the trees</h3><p>Hudson, New York · Entire home · 2 guests</p><div class="money">$3,672 <span>for 30 nights</span></div><p>Includes a $72 network fee. Deposit separate.</p></a>`}
function landing(){return `<section class="hero"><div><p class="eyebrow">A little longer. A little more at home.</p><h1>A home for<br>what’s next.</h1><p class="intro">Find your place for 30 nights or more.<br>A clear price. A 2% network fee on your stay.</p><form class="search-bar" data-form="search"><label>Where would you like to live?<input name="city" placeholder="City or region" aria-label="City or region"></label><button class="btn" type="submit">Find a home</button></form><p class="fine" style="margin-top:14px">Explore homes before creating an account.</p></div><figure>${img()}<figcaption>A sense of home · Illustrative concept</figcaption></figure></section><div class="benefits"><div><b>Settle in for 30+ nights</b><p>A home for a new chapter, a project, or a longer stay.</p></div><div><b>See the price clearly</b><p>Your stay, network fee and deposit terms, explained before you book.</p></div><div><b>Meet the person behind the home</b><p>Read their profile and ask questions before deciding.</p></div></div><section class="section"><div class="section-head"><h2>Picture your next month.</h2>${link('explore','Explore homes','secondary')}</div><div class="split equal">${homeCard()}<div class="surface"><p class="eyebrow">Straightforward by design</p><h2>Know where you stand.</h2><div class="line"><span>Illustrative 30-night stay</span><b class="money">$3,600</b></div><div class="line"><span>2% network fee</span><b class="money">$72</b></div><div class="line total"><span>Stay total</span><span class="money">$3,672</span></div><p class="small muted" style="margin-top:20px">Security deposit terms appear separately. Actual pricing depends on the home and your dates.</p></div></div><p class="catalog-note">Design preview: this home and price are examples, not live inventory.</p></section><section class="section tint"><div class="split equal"><h2>Your home.<br>Someone’s next chapter.</h2><div><p class="muted">Create a listing, add the details that matter, and get ready to welcome a longer stay. You can save your draft and return later.</p><div class="spacer"></div>${link('homeowners','Start hosting')}</div></div></section><section class="section"><h2>Good questions.</h2><details><summary>How long can I stay?</summary><p>Stead supports stays of at least 30 nights. Choose your actual dates on a home’s booking page.</p></details><details><summary>What does the 2% fee cover?</summary><p>The network fee is calculated on the stay rate and shown separately before payment. Check your final booking breakdown and deposit terms.</p></details><details><summary>Can I be a renter and a homeowner?</summary><p>Yes. Use the same account to find a stay or manage your homes.</p></details></section>`}
function homeowners(){return `<section class="hero"><div><p class="eyebrow">For homeowners</p><h1>Make room for<br>a longer stay.</h1><p class="intro">List your home for stays of 30 nights or more. Set your rate, introduce your space, and prepare to welcome a guest.</p><div class="actions">${button('start-host','Create your listing')}${link('host','See homeowner tools','quiet')}</div><p class="fine" style="margin-top:16px">Start with a draft. Finish when you’re ready.</p></div><figure>${img()}<figcaption>Room for a new chapter · Concept image</figcaption></figure></section><section class="section tint"><div class="split equal"><div><p class="eyebrow">A clear path to your first guest</p><h2>From your home<br>to a complete listing.</h2><ol class="number-list"><li><div><h3>Start with the essentials</h3><p>Tell us where your home is, what kind of space it is and how many guests it can welcome.</p></div></li><li><div><h3>Bring your home to life</h3><p>Add real photos, useful details, your rate and cancellation policy.</p></div></li><li><div><h3>Get ready to accept bookings</h3><p>Review your listing and connect your payout account. Keep track of anything still needed.</p></div></li></ol></div><div class="surface" style="background:white;align-self:center"><p class="eyebrow">Understand the fee</p><h2>Your rate stays visible.</h2><div class="line"><span>Example stay rate · 30 nights</span><b class="money">$3,600</b></div><div class="line"><span>Network fee added for renter</span><b class="money">$72</b></div><div class="line total"><span>Renter’s stay total</span><span class="money">$3,672</span></div><p class="small muted" style="margin-top:20px">This illustrates Stead’s network fee, not a guaranteed net payout. Deposit terms and payment-provider deductions must be shown where applicable.</p><div class="spacer"></div>${button('start-host','Start a draft','full')}</div></div></section>`}
function explore(){const match=(!state.query||/hudson|new york|trees|home/i.test(state.query))&&!state.instantOnly&&!state.filterMismatch;return `<div class="container"><div class="title-row"><div><p class="eyebrow">Find your place</p><h1>A month to make your own.</h1><p class="muted">Homes for stays of 30 nights or more.</p></div></div><form class="filters" data-form="filter"><label>City or region<input name="city" value="${esc(state.query)}" placeholder="Where would you like to stay?"></label><label>Home type<select name="type"><option value="">Any type</option><option>Entire home</option><option>Apartment</option><option>Private room</option></select></label><label>Guests<input name="guests" type="number" min="1" max="50" placeholder="1 or more"></label><label>Max nightly rate ($)<input name="maxRate" type="number" min="1" placeholder="Any rate"></label><button type="submit" class="btn">Show homes</button></form><div class="title-row"><label class="check-row"><input type="checkbox" id="instant" ${state.instantOnly?'checked':''}>Instant book only</label>${button('clear-filters','Clear filters','quiet')}</div>${match?`<div class="grid3">${homeCard()}</div>`:`<div class="empty-state"><h2>No homes match these filters.</h2><p>Try another city or a wider price range.</p>${button('clear-filters','Clear filters')}</div>`}<p class="catalog-note">One illustrative home is included in this prototype. Filters do not check date availability; choose dates on the home’s page.</p></div>`}
function listing(){return `<div class="container"><div class="title-row"><div><p class="eyebrow">Hudson, New York</p><h1>The house by the trees.</h1><p class="muted">Entire home · Stays of 30 nights or more</p></div>${link('explore','Back to homes','quiet')}</div>${img('listing-photo')}<div class="split"><div class="stack"><div><h2>A place to settle in.</h2><div class="facts"><span>2 guests</span><span>1 bedroom</span><span>1 bed</span><span>Kitchen</span><span>Wi-Fi</span></div></div><p class="muted">A bright living space, a table by the window, and a little quiet at the end of the day. This example shows how a homeowner’s description and real property details will appear.</p><div class="person"><span class="avatar">AL</span><div><b>Hosted by Alex</b><p>Illustrative homeowner profile</p></div></div><div class="actions">${link('passport','View host profile','secondary')}${button('message-host','Ask a question','quiet')}</div><div><h3>Before you book</h3><details><summary>Cancellation policy</summary><p>See the exact cancellation terms for your dates before payment. The implementation must use the server’s policy and refund preview.</p></details><details><summary>Security deposit</summary><p>This example has a $300 security deposit limit, with a card kept on file. It is separate from your stay total. Your booking will explain when a charge can occur and how to respond to a claim.</p></details></div></div><aside class="card sticky-card"><p class="amount money">$3,672</p><p class="muted small">Example total for 30 nights</p><div class="line"><span>$120 × 30 nights</span><span class="money">$3,600</span></div><div class="line"><span>2% network fee</span><span class="money">$72</span></div><div class="line"><span>Security deposit</span><span class="money">$300 · separate</span></div><div class="spacer"></div>${link('booking','Choose your dates','full')}<p class="fine" style="margin-top:14px">You’ll review the exact price before payment.</p></aside></div><p class="catalog-note">Concept property, image and host. No bookable inventory is represented.</p></div>`}
function login(){const host=state.intent==='homeowner';return `<div class="auth"><span class="chip">${host?'Your homeowner account':'Your Stead account'}</span><h1>${state.sent?'Check your email.':host?'Your first step to hosting.':'A place to begin.'}</h1><p class="muted">${state.sent?'Use the link to continue where you left off.':host?'Create an account or sign in to save your listing and finish it at your pace.':'Create an account or sign in with your email. Your selected home and dates will stay with you.'}</p>${state.sent?`<div class="notice" style="margin:28px 0"><b>Email-link state preview</b><p>No email was sent. Use the button below to simulate returning from the link.</p></div>${button('verify-email','Simulate email verification','full')}<div class="actions" style="margin-top:16px">${button('resend','Resend link','quiet')}${button('edit-email','Use a different email','quiet')}</div>`:`<form data-form="login" class="stack"><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><button class="btn full" type="submit">Continue with email</button></form><p class="small muted">No password needed. We’ll send a secure sign-in link.</p>`}<small>The live product must link to approved terms and privacy information. These documents are not supplied by this prototype.</small><div class="flow-note">Prototype flow: ${host?'homeowner → saved listing draft':state.next==='booking'?'selected stay → email → same dates → payment':'renter → email → chosen destination'}. Email input remains in this page only and is never transmitted.</div></div>`}
function nights(){return Math.round((Date.parse(state.checkOut+'T00:00:00Z')-Date.parse(state.checkIn+'T00:00:00Z'))/86400000)}
function costs(){const count=nights();const subtotal=12000*count;const fee=Math.trunc(subtotal*200/10000);return {count,subtotal,fee,total:subtotal+fee}}
function priceRows(){const c=costs();return `<div class="line"><span>$120 × ${c.count} nights</span><span class="money">${money(c.subtotal)}</span></div><div class="line"><span>2% network fee</span><span class="money">${money(c.fee)}</span></div><div class="line total"><span>Stay total</span><span class="money">${money(c.total)}</span></div><p class="small muted" style="margin-top:16px">$300 security deposit limit · card on file in this example. No deposit charged today.</p>`}
function booking(){const step=state.bookingStep;return `<div class="container"><div class="title-row"><div><p class="eyebrow">The house by the trees</p><h1>${['Choose your dates.','Everything in the open.','One last look.'][step-1]}</h1></div>${button('booking-back',step===1?'Back to home':'Back','quiet')}</div><ol class="progress" aria-label="Booking progress">${['Your stay','Price & terms','Confirm & pay'].map((label,i)=>`<li ${step===i+1?'aria-current="step"':''} class="${step>=i+1?'active':''}">${i+1}. ${label}</li>`).join('')}</ol><div class="split"><section>${step===1?`<form data-form="dates" class="stack"><div class="grid2"><label>Check-in<input type="date" name="checkIn" value="${esc(state.checkIn)}" required></label><label>Check-out<input type="date" name="checkOut" value="${esc(state.checkOut)}" required></label></div><label>Guests<select name="guests"><option value="1" ${state.guests===1?'selected':''}>1 guest</option><option value="2" ${state.guests===2?'selected':''}>2 guests</option></select></label><p class="muted">Choose at least 30 nights. This home welcomes up to 2 guests.</p><div id="date-error" class="notice error" hidden role="alert"></div><button class="btn" type="submit">Review price and terms</button></form>`:step===2?`<div class="stack"><div class="card"><h2>Your dates</h2><p>${esc(state.checkIn)} to ${esc(state.checkOut)}</p><p class="muted">${nights()} nights · ${state.guests} ${state.guests===1?'guest':'guests'}</p></div><div><h2>Security deposit</h2><p class="muted" style="margin-top:16px">For this example, a card is kept on file for a security deposit of up to $300. The $300 is not included in today’s stay charge. Any claim follows the terms you accept at booking.</p></div><details><summary>Cancellation terms</summary><p>Show the property’s configured cancellation policy and date-specific refund terms here. Terms must come from the booking service in production.</p></details>${button('to-payment',state.signedIn?'Continue to payment':'Sign in to continue')}<p class="fine">${state.signedIn?'Your payment details are handled by the payment provider.':'Your dates and guest count will be here when you return.'}</p></div>`:`<div class="stack"><div class="notice"><b>Payment preview</b><p>In the app, secure Stripe payment fields appear here. This prototype collects no card information.</p></div><div class="card"><h2>Your stay</h2><p>${esc(state.checkIn)} to ${esc(state.checkOut)} · ${nights()} nights</p><p class="muted">${state.guests} guests · The house by the trees</p></div><label class="check-row"><input id="accept-terms" type="checkbox">I have reviewed the cancellation and security deposit terms.</label>${button('confirm-booking',`Simulate payment · ${money(costs().total)}`,'full')}<p class="fine">Production: only show confirmation after server verification of payment and required deposit setup.</p></div>`}</section><aside class="card sticky-card">${img()}<h3 style="margin-top:22px">The house by the trees</h3><p class="muted small">Hudson, New York · Entire home</p>${priceRows()}</aside></div></div>`}
function confirmation(){return `<div class="container"><div class="title-row"><div><span class="chip">Illustrative confirmation</span><h1 style="margin-top:20px">Your next chapter is booked.</h1><p class="muted">A clear record of your stay, with everything in one place.</p></div></div><div class="split"><div class="stack">${img('listing-photo')}<div><h2>The house by the trees</h2><p class="muted" style="margin-top:12px">${esc(state.checkIn)} to ${esc(state.checkOut)} · ${nights()} nights · ${state.guests} guests</p></div><div class="actions">${link('trip','View stay details')}${link('messages','Message your host','secondary')}</div></div><aside class="card sticky-card"><h2>What happens next</h2><div class="timeline"><div><span class="number">1</span><div><b>Review your stay</b><p>Your dates, receipt and policies stay together.</p></div></div><div><span class="number">2</span><div><b>Talk with your host</b><p>Ask about arrival or anything else you need.</p></div></div><div><span class="number">3</span><div><b>Settle in</b><p>Check your stay details for arrival instructions.</p></div></div></div><p class="flow-note">No booking or payment was made. This is the success-state design.</p></aside></div></div>`}
function trips(){if(state.canceled)return `<div class="empty-state"><span class="chip neutral">Canceled · simulated</span><h1 style="margin-top:20px">Your stay was canceled.</h1><p>This shows a completed cancellation state. No real booking or refund exists in the prototype.</p>${link('explore','Find a home')}</div>`;return `<div class="container"><div class="title-row"><div><p class="eyebrow">Your stays</p><h1>Somewhere to look forward to.</h1><p class="muted">Upcoming and past stays, together.</p></div>${link('explore','Find another home','secondary')}</div><div class="booking-list"><article class="booking-row">${img()}<div><span class="chip">Confirmed · example</span><h2>The house by the trees</h2><p>Hudson, New York</p><p>${esc(state.checkIn)} to ${esc(state.checkOut)} · ${nights()} nights</p></div><div class="actions">${link('trip','View stay','secondary')}</div></article></div></div>`}
function trip(){return `<div class="container"><div class="title-row"><div><span class="chip">Confirmed · example</span><h1 style="margin-top:18px">Your stay in Hudson.</h1><p class="muted">${esc(state.checkIn)} to ${esc(state.checkOut)} · ${nights()} nights</p></div>${link('trips','All stays','quiet')}</div><div class="split"><div class="stack">${img('listing-photo')}<div class="card"><h2>Your host</h2><div class="person"><span class="avatar">AL</span><div><b>Alex</b><p>The house by the trees</p></div></div><div class="spacer"></div>${link('messages','Message your host','secondary')}</div><div><h2>Arrival and departure</h2><div class="line"><span>Check-in</span><b>${esc(state.checkIn)} · 3:00 PM</b></div><div class="line"><span>Check-out</span><b>${esc(state.checkOut)} · 11:00 AM</b></div><p class="fine">Example times · America/New_York. In production, use listing-local configuration.</p></div><div class="actions">${button('cancel-stay','Review cancellation','quiet')}${link('review','Preview post-stay review','quiet')}</div></div><aside class="stack"><div class="card"><h2>Your price</h2>${priceRows()}</div><div class="surface"><h2>Security deposit</h2><span class="chip neutral">Card on file · example</span><p class="muted" style="margin-top:16px">Up to $300 under your booking’s claim terms. No deposit charge is shown in this example.</p><div class="spacer"></div>${link('claim','Preview a claim','quiet')}</div></aside></div></div>`}
function messages(){return `<div class="container"><div class="title-row"><div><p class="eyebrow">Messages</p><h1>A good stay starts here.</h1><p class="muted">Keep the conversation with your host in one place.</p></div></div><div class="inbox"><aside class="threads"><button class="thread" type="button" data-action="open-thread"><div class="person"><span class="avatar">AL</span><div><b>Alex</b><p>The house by the trees</p></div></div><p class="small muted" style="margin-top:16px">Happy to answer your questions.</p></button></aside><section class="chat"><div class="title-row"><div><h2 style="font-size:1.4rem">Alex</h2><p class="small muted">The house by the trees</p></div>${link('listing','View home','quiet')}</div><div class="bubble"><p>Hi! Is there a table where I could work during my stay?</p><p class="fine" style="margin-top:8px">You · Example conversation</p></div><div class="bubble self"><p>Yes, there’s a table beside the window. Happy to answer any other questions about the space.</p><p class="fine" style="margin-top:8px">Alex · Example conversation</p></div>${state.message?`<div class="bubble"><p>${esc(state.message)}</p><p class="fine" style="margin-top:8px">Preview message · not sent</p></div>`:''}<form data-form="message"><label>Your message<input name="message" required maxlength="1000" placeholder="Ask about the home or your stay"></label><button class="btn" type="submit">Send message</button></form></section></div></div>`}
function passport(){return `<div class="container"><div class="title-row"><div><p class="eyebrow">Trust Passport</p><h1>A little more about Alex.</h1><p class="muted">Profile information and reputation, in one place.</p></div>${button('export-passport','Export profile','secondary')}</div><div class="split"><div class="stack"><div class="card"><div class="person"><span class="avatar" style="width:64px;height:64px;font-size:1.4rem">AL</span><div><h2 style="margin-bottom:8px">Alex</h2><p>Hudson, New York · Example member</p></div></div><div class="spacer"></div><span class="chip neutral">Email confirmed · example</span><p class="muted" style="margin-top:20px">Verified identity status and completed-stay reviews appear here when available. An email confirmation is not a government ID check.</p></div><div><h2>Reviews</h2><div class="surface" style="margin-top:20px"><h3>No completed-stay reviews yet.</h3><p class="muted" style="margin-top:12px">Reviews will appear after eligible stays. No ratings are invented for this design.</p></div></div></div><aside class="surface sticky-card"><h2>Your identity</h2><p class="muted">You can add identity verification to your profile through the verification provider.</p><div class="spacer"></div>${button('identity','Verify your identity','full')}<p class="fine" style="margin-top:16px">Own-profile action only. Other members see status, not private identity documents.</p></aside></div></div>`}
function host(){return `<div class="container">${hostNav()}<div class="title-row"><div><p class="eyebrow">Your homes</p><h1>Your place, ready for what’s next.</h1><p class="muted">Create a draft, finish the details, and keep your listing current.</p></div>${button('new-home','Add a home')}</div><div class="split"><div class="booking-list"><article class="card">${img()}<div class="title-row" style="margin-top:22px;margin-bottom:16px"><div><span class="chip ${state.published?'':'neutral'}">${state.published?'Published · example':'Draft · example'}</span><h2 style="margin-top:14px">The house by the trees</h2><p class="muted small">Hudson, New York · $120 nightly rate</p></div></div><div class="actions">${button('edit-home','Continue editing')}${link('listing','Preview listing','secondary')}${state.published?button('pause-listing','Pause listing','quiet'):''}</div></article></div><aside class="surface sticky-card"><h2>Before your first booking</h2><ul class="checklist"><li><span>Home basics</span><span>Added</span></li><li><span>Real property photos</span><a href="#edit">Review</a></li><li><span>Rate and policies</span><a href="#edit">Review</a></li><li><span>Payout account</span><a href="#payouts">${state.payoutReady?'Ready':'Set up'}</a></li></ul><p class="small muted" style="margin-top:22px">Published and ready to accept payments are separate states. Complete payout setup before a guest can pay.</p></aside></div></div>`}
function edit(){const step=state.editStep;const labels=['Basics','Home details','Price & policy','Photos','Review'];let body='';if(step===1)body=`<label>Listing title<input name="title" required value="The house by the trees" minlength="3"></label><div class="grid2"><label>Home type<select name="type"><option>Entire home</option><option>Apartment</option><option>Private room</option></select></label><label>Guests<input type="number" name="guests" value="2" min="1" max="50" required></label></div><div class="grid2"><label>City<input name="city" value="Hudson" required></label><label>Country<select name="country"><option value="US">United States</option></select></label></div><label>Time zone<select name="timezone"><option value="America/New_York">Eastern time · New York</option><option value="America/Los_Angeles">Pacific time · Los Angeles</option></select></label><p class="fine">Use the home’s time zone for arrivals and departures. Suggestions must be confirmed for the property.</p>`;
if(step===2)body=`<label>About your home<textarea name="description">A bright living space with a table by the window and a leafy outlook.</textarea></label><label>Street address<input name="address" value="" placeholder="Property address"></label><p class="fine">Production must follow the documented address-visibility policy; do not expose an exact address through a public listing response.</p><fieldset><legend>What’s available?</legend><div class="grid2"><label class="check-row"><input type="checkbox" name="wifi" checked>Wi-Fi</label><label class="check-row"><input type="checkbox" name="kitchen" checked>Kitchen</label><label class="check-row"><input type="checkbox" name="fireplace">Fireplace</label><label class="check-row"><input type="checkbox" name="courtyard">Courtyard</label></div></fieldset>`;
if(step===4)body=`<div class="notice"><b>Photos of the actual home</b><p>Use clear, accurate images of every important space. The image below is a concept placeholder for this preview.</p></div>${img()}<label>Add photos<input type="file" accept="image/jpeg,image/png,image/webp" multiple name="photos"></label><p class="fine">Preview only: selected files are not uploaded. The implementation must use existing presigned uploads and allow accessible removal and upload retry; ordering requires separately scoped API work.</p>`;
if(step===3)body=`<div class="grid2"><label>Nightly rate ($)<input name="rate" type="number" min="1" step="1" value="120" required></label><label>Security deposit limit ($)<input name="deposit" type="number" min="0" step="1" value="300" required></label></div><label>Cancellation policy<select name="policy"><option value="flexible">Flexible</option><option value="moderate">Moderate</option><option value="strict">Strict</option></select></label><details><summary>Review this policy</summary><p>The live implementation must show the exact server-defined cancellation conditions, not infer them from the policy name.</p></details><label class="check-row"><input type="checkbox" name="instant">Allow instant booking</label><div class="surface"><div class="line"><span>Example 30-night stay rate</span><b class="money">$3,600</b></div><div class="line"><span>Renter network fee</span><b class="money">$72</b></div><p class="small muted" style="margin-top:16px">This is a pricing illustration, not an estimate of net bank proceeds.</p></div>`;
if(step===5)body=`<div class="card">${img()}<h2 style="margin-top:22px">${esc(state.hostFields?.title||'The house by the trees')}</h2><p class="muted">${esc(state.hostFields?.city||'Hudson')} · ${esc(state.hostFields?.type||'Entire home')} · ${esc(state.hostFields?.guests||2)} guests</p><div class="line"><span>Nightly rate</span><b class="money">${money(Number(state.hostFields?.rate||120)*100)}</b></div><div class="line"><span>Security deposit limit</span><b class="money">${money(Number(state.hostFields?.deposit??300)*100)}</b></div><div class="line"><span>Minimum stay</span><b>30 nights</b></div></div><div class="notice"><b>${state.payoutReady?'Payout setup complete in this preview':'One more thing: payout setup'}</b><p>${state.payoutReady?'Review every detail before publishing.':'You can save your draft now. Your account must be able to receive payments before guests can book.'}</p></div>${link('payouts','Review payout setup','secondary')}<p class="fine">Publishing below is simulated. Only genuine property photos and verified operational readiness belong in production.</p>`;
return `<div class="container"><div class="title-row"><div><p class="eyebrow">Create your listing · ${step} of 5</p><h1>${['Start with your home.','The details make it yours.','A clear price and policy.','Let your space speak.','Ready for a final look?'][step-1]}</h1></div>${button('save-draft','Save and exit','secondary')}</div><ol class="progress">${labels.map((l,i)=>`<li class="${step>=i+1?'active':''}" ${step===i+1?'aria-current="step"':''}>${l}</li>`).join('')}</ol><div class="split"><form data-form="listing" class="stack">${body}<div class="actions">${step>1?button('edit-back','Back','secondary'):''}<button class="btn" type="submit">${step===5?'Simulate publish':step===3?'Save draft and add photos':'Continue'}</button></div></form><aside class="surface sticky-card"><p class="eyebrow">A home, honestly described</p><h2>Help someone picture their stay.</h2><p class="muted">Clear photos, useful details and a realistic rate help renters make an informed choice.</p><div class="spacer"></div><p class="small muted">Your account can rent and host. This listing is a draft until you choose to publish.</p><div class="flow-note">This prototype simulates step progression. Form fields remain in memory while you move between steps. They are not saved after reload. Durable draft persistence is specified in the build plan.</div></aside></div></div>`}
function payouts(){return `<div class="container">${hostNav()}<div class="title-row"><div><p class="eyebrow">Payouts</p><h1>Know where your money stands.</h1><p class="muted">Your payment-account readiness and payout records.</p></div></div><div class="split"><section class="card"><span class="chip ${state.payoutReady?'':'warn'}">${state.payoutReady?'Ready · simulated':'Setup needed'}</span><h2 style="margin-top:22px">${state.payoutReady?'Your payout account is connected.':'Connect your payout account.'}</h2><p class="muted">${state.payoutReady?'This is the ready-state preview. Live status must come from Stripe, including charges and payouts readiness.':'Complete the required details with Stripe so your account can receive payments.'}</p><div class="spacer"></div>${button('connect-payouts',state.payoutReady?'Review Stripe setup':'Continue to Stripe','full')}<p class="fine" style="margin-top:14px">Demo: the button previews the external-provider handoff. No provider connection occurs.</p></section><aside class="surface"><h2>What to expect</h2><p class="muted">The provider may need identity or banking details. Return here to check the status and complete any outstanding requirements.</p><div class="spacer"></div><p class="small muted">A payment received and a payout arriving in your bank are separate events. Use the current provider status for timing.</p></aside></div><div class="spacer"></div><section class="card"><h2>Payout history</h2><p class="muted">No payout records yet. Your records will appear here after eligible activity.</p></section></div>`}
function claims(){return `<div class="container">${hostNav()}<div class="title-row"><div><p class="eyebrow">Claims</p><h1>Clear records. Clear next steps.</h1><p class="muted">Review evidence, responses and outcomes for a stay.</p></div></div><article class="card"><div class="title-row" style="margin-bottom:12px"><div><span class="chip warn">Awaiting response · example</span><h2 style="margin-top:18px">The house by the trees</h2><p class="muted">Example claim · Damage to a table</p></div><strong class="amount money">$80</strong></div><div class="actions">${link('claim','Review claim')}${button('file-claim','Preview filing a claim','secondary')}</div><p class="flow-note">New claims originate from eligible stay details during the server-defined claim window. A generic “file against any stay” action must not be added to production.</p></article></div>`}
function claim(){return `<div class="container"><div class="title-row"><div><span class="chip warn">${state.claimDisputed?'Disputed · simulated':'Response needed · example'}</span><h1 style="margin-top:18px">Review the claim.</h1><p class="muted">The house by the trees · Illustrative claim for $80</p></div>${link('claims','All claims','quiet')}</div><div class="split"><div class="stack"><div class="card"><h2>What the homeowner reported</h2><p class="muted">“A new mark on the oak table was found after checkout.”</p><div class="line"><span>Requested amount</span><b class="money">$80</b></div><p class="fine">Example text, not an actual claim or allegation.</p></div><div class="surface"><h2>Evidence</h2><p class="muted">Actual photos and supporting information appear here. The illustrative home photo is not used as evidence.</p>${button('evidence','View evidence state','quiet')}</div><div><h2>Activity</h2><div class="timeline"><div><span class="number">1</span><div><b>Claim received</b><p>Evidence and amount recorded.</p></div></div><div><span class="number">2</span><div><b>${state.claimDisputed?'Response recorded':'Your response'}</b><p>${state.claimDisputed?'Both parties can see the next steps.':'Review the evidence before accepting or disputing.'}</p></div></div></div></div></div><aside class="card sticky-card"><h2>Your response</h2><p class="muted">Review the amount and evidence. If you disagree, record a dispute and add supporting evidence where permitted.</p><div class="spacer"></div><div class="stack small-gap">${button('accept-claim','Review acceptance of $80','secondary')}${button('dispute-claim','Dispute claim')}</div><p class="flow-note">Guest response view. The implementation must render homeowner, guest and arbiter controls from server permissions; a route is not authorization.</p></aside></div></div>`}
function review(){return `<div class="container"><div class="title-row"><div><p class="eyebrow">After your stay</p><h1>${state.reviewSent?'Thank you for sharing.':'How was your stay?'}</h1><p class="muted">The house by the trees · Eligible completed stay example</p></div></div><div class="split"><section>${state.reviewSent?`<div class="notice"><b>Review submitted · simulated</b><p>The live review publishes according to the server’s double-blind rules, not immediately on submit.</p></div><div class="spacer"></div>${link('trips','Back to stays')}`:`<form class="stack" data-form="review"><fieldset><legend>Overall rating</legend><div class="actions">${[1,2,3,4,5].map(n=>`<label class="pill-choice"><input type="radio" name="rating" value="${n}" required>${n}</label>`).join('')}</div></fieldset><label>Your review (optional)<textarea name="review" maxlength="4000" placeholder="What would help another guest understand this home?"></textarea></label><button class="btn" type="submit">Submit review</button><p class="fine">Preview only. Your text is not sent or published.</p></form>`}</section><aside class="surface"><h2>Useful, specific, fair.</h2><p class="muted">Describe what you experienced. Keep private details out of your review.</p><div class="spacer"></div><p class="small muted">Only eligible stays can be reviewed. Publication waits for both parties or the configured review window.</p></aside></div></div>`}
function ops(){return `<div class="container"><div class="title-row"><div><p class="eyebrow">Operations · restricted access</p><h1>What needs attention.</h1><p class="muted">Payment disputes, job health and frozen payouts.</p></div>${button('refresh','Refresh status','secondary')}</div><div class="notice"><b>Operator preview</b><p>This view is restricted to authorized operators in production. Its presence in this offline prototype grants no access.</p></div><div class="spacer"></div><div class="grid3"><div class="card"><h2>Payment disputes</h2><p class="muted">No disputes in this example.</p></div><div class="card"><h2>Frozen payouts</h2><p class="muted">No frozen payouts in this example.</p></div><div class="card"><h2>Scheduled jobs</h2><span class="chip warn">Review needed · example</span><p class="muted" style="margin-top:12px">One illustrative stale heartbeat.</p></div></div><div class="spacer"></div><div class="card"><h2>Job health</h2><div class="table-scroll"><table><thead><tr><th scope="col">Job</th><th scope="col">Status</th><th scope="col">Last successful run</th></tr></thead><tbody><tr><td>Expire pending bookings</td><td><span class="chip warn">Stale · example</span></td><td>Illustrative timestamp</td></tr></tbody></table></div><p class="flow-note">No rerun, refund, or money-movement controls are invented. Use the operational runbook and actual permitted backend actions.</p></div></div>`}
const views = {landing,homeowners,explore,listing,login,booking,confirmation,trips,trip,messages,passport,host,edit,payouts,claims,claim,review,ops};
function stateView(){if(state.view==='loading')return `<div class="container" role="status" aria-live="polite"><p class="eyebrow">${screens[state.page].slice(5)}</p><h1>Getting things ready.</h1><p class="muted" style="margin-top:18px">Your information is loading.</p><div class="skeleton large" aria-hidden="true"></div><div class="skeleton" aria-hidden="true"></div><div class="skeleton" style="width:70%" aria-hidden="true"></div></div>`;const empty={explore:['No homes found.','Try another city or widen your filters.','explore','Clear filters'],trips:['Your first stay starts here.','When you book a home, your stay details will appear here.','explore','Find a home'],messages:['No conversations yet.','Find a home and ask the homeowner a question.','explore','Explore homes'],host:['Make a place for your home.','Start with a draft. You can finish the details later.','edit','Create a listing'],claims:['No claims to review.','Any claims you are involved in will appear here.','host','Your homes'],payouts:['No payout records yet.','Complete your payout setup before your first guest books.','payouts','Review setup'],passport:['No reviews yet.','Eligible completed-stay reviews will appear on this profile.','explore','Explore homes'],login:['Ready when you are.','Use your email to create an account or sign in.','login','Continue']};if(state.view==='empty'){const c=empty[state.page]||['Nothing here yet.','Return to the previous step to continue.','landing','Back to home'];return `<div class="empty-state"><h1>${c[0]}</h1><p>${c[1]}</p>${link(c[2],c[3])}</div>`}return `<div class="empty-state"><p class="eyebrow">${state.page==='login'?'Link expired or already used':'Something needs another try'}</p><h1>${state.page==='login'?'Let’s get you a new link.':'We couldn’t load this.'}</h1><p>${state.page==='login'?'Request another email link. Your selected home or listing draft should remain available.':'Your work should stay saved. Check your connection and try again.'}</p>${button('retry',state.page==='login'?'Request a new link':'Try again')}<p class="fine">No sensitive service errors are exposed to members.</p></div>`}
function rememberListing(){const form=document.querySelector('[data-form="listing"]');if(!form)return;state.hostFields??={};for(const el of form.elements){if(!el.name||el.type==='file')continue;state.hostFields[el.name]=el.type==='checkbox'?el.checked:el.value}}
function restoreListing(){if(state.page!=='edit'||!state.hostFields)return;const form=document.querySelector('[data-form="listing"]');if(!form)return;for(const el of form.elements){if(!el.name||el.type==='file'||!(el.name in state.hostFields))continue;if(el.type==='checkbox')el.checked=state.hostFields[el.name];else el.value=state.hostFields[el.name]}}
function render(){const page=views[state.page]||landing;$('#app').innerHTML=header()+`<main>${state.view==='default'?page():stateView()}</main>`+footer()+(['login','booking','edit','confirmation'].includes(state.page)?'':bottom());$('#screen-picker').value=state.page;document.title=`Stead · ${screens[state.page]||'Design preview'}`;restoreListing();}
function go(page){if(!screens[page])page='landing';if(location.hash.slice(1)===page){state.page=page;render();}else location.hash=page;}
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true},4500)}
function modal(title,body,actions){$('#dialog').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="actions">${actions}${button('close-dialog','Close','secondary')}</div>`;$('#dialog').showModal()}
function requireAccount(next,intent='renter'){state.next=next;state.intent=intent;state.sent=false;if(state.signedIn)go(next);else go('login')}
document.addEventListener('click',e=>{
 const a=e.target.closest('a[href^="#"]');if(a){const id=a.getAttribute('href').slice(1);if(screens[id]){e.preventDefault();if($('#dialog').open)$('#dialog').close();if(a.dataset.next){state.next=a.dataset.next;state.intent='renter';state.sent=false}state.view='default';$('#state-picker').value='default';go(id);return}}
 const el=e.target.closest('[data-action]');if(!el)return;
 switch(el.dataset.action){
  case 'start-host':state.editStep=1;requireAccount('edit','homeowner');break;
  case 'new-home':state.editStep=1;go('edit');break;
  case 'edit-home':state.editStep=1;go('edit');break;
  case 'message-host':requireAccount('messages');break;
  case 'verify-email':state.signedIn=true;state.sent=false;go(state.next);toast('Email verification simulated. Your chosen destination is preserved.');break;
  case 'resend':toast('A new-link request would be sent in the live app.');break;
  case 'edit-email':state.sent=false;render();break;
  case 'booking-back':if(state.bookingStep>1){state.bookingStep--;render()}else go('listing');break;
  case 'to-payment':state.bookingStep=3;requireAccount('booking');break;
  case 'confirm-booking':if(!$('#accept-terms').checked){toast('Review the terms and select the checkbox before continuing.');$('#accept-terms').focus();break}state.bookingConfirmed=true;state.canceled=false;go('confirmation');break;
  case 'clear-filters':state.query='';state.instantOnly=false;state.filterMismatch=false;state.view='default';$('#state-picker').value='default';render();break;
  case 'open-thread':toast('Showing your example conversation with Alex.');break;
  case 'edit-back':rememberListing();state.editStep=Math.max(1,state.editStep-1);render();break;
  case 'save-draft':rememberListing();state.draftSaved=true;go('host');toast('Draft-save state simulated. Production persistence follows the build plan.');break;
  case 'pause-listing':state.published=false;render();toast('Listing paused in this preview.');break;
  case 'connect-payouts':modal('Continue with Stripe',`<p>The live app opens the payment provider’s secure setup. It returns here to verify account readiness.</p><p class="fine">Preview only. Simulate a completed provider return to see the ready state.</p>`,button('payout-return','Simulate completed setup'));break;
  case 'payout-return':state.payoutReady=true;$('#dialog').close();render();toast('Provider-ready state simulated. No banking details were collected.');break;
  case 'cancel-stay':modal('Review cancellation',`<p>Example refund preview for an eligible stay. The live amount and consequences must be returned by the server before confirmation.</p><div class="line"><span>Example refundable stay amount</span><b class="money">${money(costs().total)}</b></div><p class="fine">No real stay exists in this prototype. This is a destructive-action review pattern.</p>`,button('cancel-confirm','Simulate cancellation','danger'));break;
  case 'cancel-confirm':state.canceled=true;$('#dialog').close();go('trips');toast('Cancellation simulated. No booking changed.');break;
  case 'accept-claim':modal('Accept the example claim?',`<p>Accepting an $80 claim in the real app can authorize a charge under the booking’s deposit terms. Review the evidence first.</p><p class="fine">This button only demonstrates the confirmation pattern.</p>`,button('accept-claim-confirm','Simulate accepting $80'));break;
  case 'accept-claim-confirm':$('#dialog').close();toast('Acceptance simulated. No money moved.');break;
  case 'dispute-claim':modal('Dispute the example claim?',`<p>Confirm that you disagree with this claim. In the live app, this records your response and follows the existing dispute process.</p><p class="fine">The current response API records acceptance or dispute. Supporting material belongs in the permitted evidence flow; no separate reason field is sent here.</p>`,button('dispute-confirm','Simulate dispute'));break;
  case 'dispute-confirm':state.claimDisputed=true;$('#dialog').close();render();toast('Dispute response simulated. Nothing was submitted.');break;
  case 'evidence':modal('Evidence preview','<p>Evidence images, timestamps and attribution appear here only when supplied by the parties. No evidence was fabricated for this prototype.</p>','');break;
  case 'file-claim':modal('File a claim from a stay','<p>In the app, open the eligible stay, review the claim-window deadline, enter an amount and explanation, and attach evidence. Submission requires server authorization and confirmation.</p><p class="fine">This prototype shows the entry and confirmation patterns; the full filing states are in the screen specifications.</p>',link('trip','View example stay'));break;
  case 'export-passport':toast('The live app exports the signed profile through the existing export endpoint. No fictional reputation file is created here.');break;
  case 'identity':modal('Verify your identity','<p>The live app opens the identity provider’s secure flow. Private identity documents remain outside this prototype.</p><p class="fine">Provider cancel, failure, pending and verified states are specified in the handoff.</p>','');break;
  case 'close-dialog':$('#dialog').close();break;
  case 'refresh':toast('Example operational status refreshed. No live service queried.');break;
  case 'retry':state.view='default';state.sent=false;$('#state-picker').value='default';render();break;
 }
});
document.addEventListener('submit',e=>{
 const kind=e.target.dataset.form;if(!kind||kind==='search')return;e.preventDefault();const fd=new FormData(e.target);
 if(kind==='login'){state.sent=true;render()}
 if(kind==='dates'){const start=String(fd.get('checkIn'));const end=String(fd.get('checkOut'));const duration=Math.round((Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000);if(!Number.isFinite(duration)||duration<30){$('#date-error').textContent='Choose a check-out date at least 30 nights after check-in.';$('#date-error').hidden=false;return}state.checkIn=start;state.checkOut=end;state.guests=Number(fd.get('guests'));state.bookingStep=2;render()}
 if(kind==='filter'){state.query=String(fd.get('city')||'');state.filterMismatch=!!((fd.get('type')&&fd.get('type')!=='Entire home')||(fd.get('guests')&&Number(fd.get('guests'))>2)||(fd.get('maxRate')&&Number(fd.get('maxRate'))<120));render()}
 if(kind==='message'){state.message=String(fd.get('message')).trim();render();toast('Message shown in preview only. Nothing was sent.')}
 if(kind==='listing'){rememberListing();if(state.editStep<5){state.editStep++;render();if(state.editStep===4)toast('Draft creation simulated before the photo-upload step.')}else{state.published=true;state.draftSaved=true;go('host');toast('Published-state preview. No real listing was created.')}}
 if(kind==='review'){state.reviewSent=true;render();toast('Review-submitted state simulated. Nothing was published.')}
});
document.addEventListener('change',e=>{if(e.target.id==='instant'){state.instantOnly=e.target.checked;render()}});
$('#screen-picker').innerHTML=Object.entries(screens).map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
$('#screen-picker').addEventListener('change',e=>go(e.target.value));
$('#layout-picker').addEventListener('change',e=>$('#stage').classList.toggle('narrow',e.target.value==='narrow'));
$('#state-picker').addEventListener('change',e=>{state.view=e.target.value;render()});
window.addEventListener('hashchange',()=>{state.page=screens[location.hash.slice(1)]?location.hash.slice(1):'landing';state.view='default';$('#state-picker').value='default';render();$('#app').focus({preventScroll:true});window.scrollTo(0,0)});
document.addEventListener('submit',e=>{if(e.target.dataset.form==='search'){e.preventDefault();state.query=new FormData(e.target).get('city')||'';go('explore')}});
state.page=screens[location.hash.slice(1)]?location.hash.slice(1):'landing';render();
